exercise.referenceSolution:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    size_t size = 0, capacity = 4;
    int *data = malloc(capacity * sizeof *data);
    if (data == NULL) {
        return 1;
    }
    char command[8];
    while (scanf("%7s", command) == 1) {
        if (strcmp(command, "insert") == 0) {
            long long i;
            int x;
            if (scanf("%lld %d", &i, &x) != 2) {
                break;
            }
            if (i < 0 || (size_t)i > size) {
                printf("ошибка\n");
                continue;
            }
            if (size == capacity) {
                int *grown = realloc(data, 2 * capacity * sizeof *data);
                if (grown == NULL) {
                    free(data);
                    return 1;
                }
                data = grown;
                capacity *= 2;
            }
            memmove(&data[i + 1], &data[i], (size - (size_t)i) * sizeof *data);
            data[i] = x;
            size++;
        } else if (strcmp(command, "erase") == 0) {
            long long i;
            if (scanf("%lld", &i) != 1) {
                break;
            }
            if (i < 0 || (size_t)i >= size) {
                printf("ошибка\n");
                continue;
            }
            memmove(&data[i], &data[i + 1], (size - (size_t)i - 1) * sizeof *data);
            size--;
        } else if (strcmp(command, "print") == 0) {
            if (size == 0) {
                printf("пусто\n");
            }
            for (size_t k = 0; k < size; k++) {
                printf(k + 1 < size ? "%d " : "%d\n", data[k]);
            }
        }
    }
    free(data);
    return 0;
}

